// Extract data from webhook and prepare for Gmail search
const body = $input.first().json.body || $input.first().json;
const attachments = body.attachments || [];

// Extract REF number from subject (e.g. 'TWF - Salida XXX - Ref A7529' -> 'A7529')
const refMatch = body.subject?.match(/Ref\s+(\w+)/i);
const refNumber = refMatch ? refMatch[1] : '';

const output = {
  to: body.to,
  subject: body.subject,
  htmlBody: body.htmlBody,
  replyTo: body.replyTo || '',
  threadId: body.threadId || '',
  refNumber: refNumber,
  hasAttachments: attachments.length > 0,
};

// Convert base64 attachments to n8n binary data
const binaryData = {};
for (let i = 0; i < attachments.length; i++) {
  const att = attachments[i];
  binaryData[`attachment_${i}`] = {
    data: att.data,
    mimeType: att.type || 'application/octet-stream',
    fileName: att.name || `attachment_${i}`,
  };
}

return [{ json: output, binary: Object.keys(binaryData).length > 0 ? binaryData : undefined }];

// Merge: original data from 'Procesar Datos' + found thread from Gmail search
const original = $('Procesar Datos').first().json;
const binaryData = $('Procesar Datos').first().binary;

// Check if Gmail search found a matching email
const searchResult = $input.first().json;
let finalSubject = original.subject;
let threadId = original.threadId || '';

if (searchResult && searchResult.threadId) {
  threadId = searchResult.threadId;
  // Use the ORIGINAL conversation subject so Gmail threads it correctly
  const origSubject = (searchResult.subject || '').replace(/^(Re:\s*)+/i, '').trim();
  if (origSubject) {
    finalSubject = 'Re: ' + origSubject;
  }
}

return [{
  json: {
    to: original.to,
    subject: finalSubject,
    htmlBody: original.htmlBody,
    threadId: threadId,
    hasAttachments: original.hasAttachments,
  },
  binary: binaryData || undefined,
}];
